248	/// LLM に許可するコマンド。他の OS 向けのコマンドまで許可しないよう OS ごとに持つ
249	#[derive(Debug, Default, Deserialize)]
250	#[serde(deny_unknown_fields, default)]
251	pub struct AllowedCommands {
252	    pub windows: Vec<String>,
253	    pub linux: Vec<String>,
254	}
255	
256	impl AllowedCommands {
257	    /// 実行中の OS の分だけを返す
258	    pub fn current(&self) -> &[String] {
259	        self.for_os(cfg!(windows))
260	    }
261	
262	    fn for_os(&self, windows: bool) -> &[String] {
263	        if windows { &self.windows } else { &self.linux }
264	    }
265	}
