291	fn log_level<'de, D: Deserializer<'de>>(deserializer: D) -> Result<LevelFilter, D::Error> {
292	    let text = String::deserialize(deserializer)?;
293	    text.parse().map_err(serde::de::Error::custom)
294	}
295	
296	fn duration<'de, D: Deserializer<'de>>(deserializer: D) -> Result<Duration, D::Error> {
297	    let text = String::deserialize(deserializer)?;
298	    parse_duration(&text).map_err(serde::de::Error::custom)
299	}
300	
301	/// "500ms" "3s" "5m" "6h" "7d" 形式の期間を解釈する
302	pub fn parse_duration(text: &str) -> std::result::Result<Duration, String> {
303	    let error = || format!("invalid duration: {text:?} (expected e.g. 500ms, 3s, 5m, 6h, 7d)");
304	    let split = text.find(|c: char| !c.is_ascii_digit()).ok_or_else(error)?;
305	    let (number, unit) = text.split_at(split);
306	    let number: u64 = number.parse().map_err(|_| error())?;
307	    let millis = match unit {
308	        "ms" => Some(1),
309	        "s" => Some(1000),
310	        "m" => Some(60_000),
311	        "h" => Some(3_600_000),
312	        "d" => Some(86_400_000),
313	        _ => None,
314	    };
315	    millis
316	        .and_then(|unit| number.checked_mul(unit))
317	        .map(Duration::from_millis)
318	        .ok_or_else(error)
319	}
320	
321	impl Config {
322	    pub fn load(path: &Path) -> Result<Self> {
323	        let text = std::fs::read_to_string(path)
324	            .with_context(|| format!("failed to read {}", path.display()))?;
325	        Self::parse(&text).with_context(|| format!("invalid config: {}", path.display()))
326	    }
327	
328	    fn parse(text: &str) -> Result<Self> {
329	        let config: Self = toml::from_str(text)?;
330	        config.validate()?;
331	        Ok(config)
332	    }
333	
334	    pub fn watch(&self, name: &str) -> Result<&Watch> {
335	        self.watches
336	            .iter()
337	            .find(|watch| watch.name == name)
338	            .with_context(|| format!("no such watch: {name}"))
339	    }
340	
341	    fn backend_defined(&self, kind: BackendKind) -> bool {
342	        match kind {
343	            BackendKind::ClaudeCode => self.backends.claude_code.is_some(),
344	            BackendKind::Codex => self.backends.codex.is_some(),
345	            BackendKind::Local => self.backends.local.is_some(),
346	        }
347	    }
348	
349	    fn validate(&self) -> Result<()> {
350	        let mut names = HashSet::new();
351	        for watch in &self.watches {
352	            // ディレクトリ名と systemd のユニット名にそのまま使うので文字種を絞る
353	            ensure!(
354	                is_safe_name(&watch.name),
355	                "watch name must be [A-Za-z0-9_-]+: {:?}",
356	                watch.name
357	            );
358	            ensure!(
359	                names.insert(&watch.name),
360	                "duplicate watch name: {}",
361	                watch.name
362	            );
363	            self.validate_watch(watch)
364	                .with_context(|| format!("watch {:?}", watch.name))?;
365	        }
366	        Ok(())
367	    }
368	
369	    fn validate_watch(&self, watch: &Watch) -> Result<()> {
370	        watch.probe.validate()?;
371	        if let Some(trigger) = &watch.trigger {
372	            ensure!(trigger.consecutive >= 1, "consecutive must be at least 1");
373	        }
374	        if let Some(diagnose) = &watch.diagnose {
375	            for kind in std::iter::once(diagnose.backend).chain(diagnose.fallback) {
376	                ensure!(
377	                    self.backend_defined(kind),
378	                    "backend {} is not configured in [backends]",
379	                    kind.name()
380	                );
381	            }
382	        }
383	        Ok(())
384	    }
385	}
386	
387	impl Probe {
388	    fn validate(&self) -> Result<()> {
389	        if self.kind == ProbeKind::Command {
390	            ensure!(!self.command.is_empty(), "command probe needs `command`");
391	            ensure!(self.targets.is_empty(), "command probe takes no `targets`");
392	            return Ok(());
393	        }
394	        ensure!(!self.targets.is_empty(), "probe needs `targets`");
395	        for target in &self.targets {
396	            match self.kind {
397	                ProbeKind::Tcp => {
398	                    let has_port = target
399	                        .rsplit_once(':')
400	                        .is_some_and(|(_, port)| port.parse::<u16>().is_ok());
401	                    if !has_port && target != "gateway" {
402	                        bail!("tcp target needs a port: {target}");
403	                    }
404	                }
405	                ProbeKind::Http => {
406	                    if !target.starts_with("http://") && !target.starts_with("https://") {
407	                        bail!("http target must be a URL: {target}");
408	                    }
409	                }
410	                ProbeKind::Icmp | ProbeKind::Dns | ProbeKind::Command => {}
411	            }
412	        }
413	        Ok(())
414	    }
415	}
