417	#[cfg(test)]
418	mod tests {
419	    use super::*;
420	
421	    const MINIMAL_WATCH: &str = r#"
422	        [[watch]]
423	        name = "w"
424	        [watch.probe]
425	        kind = "tcp"
426	        targets = ["192.0.2.1:443"]
427	    "#;
428	
429	    #[test]
430	    fn example_config_is_valid() {
431	        let config = Config::parse(include_str!("../config.example.toml")).unwrap();
432	        let watch = config.watch("network-reachability").unwrap();
433	        assert_eq!(watch.interval, Duration::from_secs(300));
434	        assert_eq!(watch.probe.kind, ProbeKind::Tcp);
435	        assert_eq!(watch.baseline.aggregate_by, AggregateBy::WeekdayHour);
436	        assert_eq!(
437	            watch.baseline.snapshot_collectors.last(),
438	            Some(&CollectorSpec::Traceroute("1.1.1.1".to_string()))
439	        );
440	        let diagnose = watch.diagnose.as_ref().unwrap();
441	        assert_eq!(diagnose.backend, BackendKind::ClaudeCode);
442	        assert_eq!(diagnose.fallback, Some(BackendKind::Local));
443	        let allowed = &diagnose.allowed_commands;
444	        assert!(allowed.windows.contains(&"tracert".to_string()));
445	        assert!(!allowed.windows.contains(&"traceroute".to_string()));
446	        assert!(allowed.linux.contains(&"traceroute".to_string()));
447	        assert!(!allowed.linux.contains(&"tracert".to_string()));
448	    }
449	
450	    #[test]
451	    fn optional_sections_get_defaults() {
452	        let config = Config::parse(MINIMAL_WATCH).unwrap();
453	        let watch = config.watch("w").unwrap();
454	        assert_eq!(watch.interval, Duration::from_secs(300));
455	        assert_eq!(watch.probe.timeout, Duration::from_secs(3));
456	        assert_eq!(watch.baseline.min_samples, 30);
457	        assert!(watch.trigger.is_none());
458	        assert_eq!(config.general.log_retention_days, 14);
459	    }
460	
461	    #[test]
462	    fn parses_durations() {
463	        assert_eq!(parse_duration("500ms"), Ok(Duration::from_millis(500)));
464	        assert_eq!(parse_duration("3s"), Ok(Duration::from_secs(3)));
465	        assert_eq!(parse_duration("5m"), Ok(Duration::from_secs(300)));
466	        assert_eq!(parse_duration("6h"), Ok(Duration::from_secs(21600)));
467	        assert_eq!(parse_duration("7d"), Ok(Duration::from_secs(604800)));
468	        for bad in ["", "5", "m", "5x", "-5m", "1.5h"] {
469	            assert!(parse_duration(bad).is_err(), "{bad:?} should be rejected");
470	        }
471	    }
472	
473	    #[test]
474	    fn rejects_typos_in_keys() {
475	        let text = MINIMAL_WATCH.replace("targets", "target");
476	        assert!(Config::parse(&text).is_err());
477	    }
478	
479	    #[test]
480	    fn rejects_unsafe_and_duplicate_watch_names() {
481	        assert!(Config::parse(&MINIMAL_WATCH.replace("\"w\"", "\"../evil\"")).is_err());
482	        assert!(Config::parse(&format!("{MINIMAL_WATCH}{MINIMAL_WATCH}")).is_err());
483	    }
484	
485	    #[test]
486	    fn tcp_targets_need_a_port_except_gateway() {
487	        let with_target = |t: &str| MINIMAL_WATCH.replace("192.0.2.1:443", t);
488	        assert!(Config::parse(&with_target("gateway")).is_ok());
489	        assert!(Config::parse(&with_target("gateway:80")).is_ok());
490	        assert!(Config::parse(&with_target("[::1]:443")).is_ok());
491	        assert!(Config::parse(&with_target("192.0.2.1")).is_err());
492	    }
493	
494	    #[test]
495	    fn diagnose_backend_must_be_configured() {
496	        let text = format!(
497	            "{MINIMAL_WATCH}\n[watch.diagnose]\nbackend = \"codex\"\nprompt_file = \"p.md\"\n"
498	        );
499	        assert!(Config::parse(&text).is_err());
500	        let text = format!("[backends.codex]\ncommand = \"codex\"\n{text}");
501	        assert!(Config::parse(&text).is_ok());
502	    }
503	
504	    fn with_allowed_commands(table: &str) -> String {
505	        format!(
506	            "[backends.codex]\ncommand = \"codex\"\n{MINIMAL_WATCH}\n\
507	             [watch.diagnose]\nbackend = \"codex\"\nprompt_file = \"p.md\"\n{table}"
508	        )
509	    }
510	
511	    #[test]
512	    fn allowed_commands_are_selected_per_os() {
513	        let text = with_allowed_commands(
514	            "[watch.diagnose.allowed_commands]\nwindows = [\"tracert\"]\nlinux = [\"traceroute\"]\n",
515	        );
516	        let config = Config::parse(&text).unwrap();
517	        let diagnose = config.watch("w").unwrap().diagnose.as_ref().unwrap();
518	        assert_eq!(diagnose.allowed_commands.for_os(true), ["tracert"]);
519	        assert_eq!(diagnose.allowed_commands.for_os(false), ["traceroute"]);
520	    }
521	
522	    #[test]
523	    fn omitted_os_allows_no_commands() {
524	        let text = with_allowed_commands("[watch.diagnose.allowed_commands]\nlinux = [\"ping\"]\n");
525	        let config = Config::parse(&text).unwrap();
526	        let diagnose = config.watch("w").unwrap().diagnose.as_ref().unwrap();
527	        assert!(diagnose.allowed_commands.for_os(true).is_empty());
528	    }
529	
530	    #[test]
531	    fn rejects_unknown_os_and_flat_allowed_commands() {
532	        let unknown = "[watch.diagnose.allowed_commands]\nwindow = [\"ping\"]\n";
533	        assert!(Config::parse(&with_allowed_commands(unknown)).is_err());
534	        let flat = "allowed_commands = [\"ping\"]\n";
535	        assert!(Config::parse(&with_allowed_commands(flat)).is_err());
536	    }
537	
538	    #[test]
539	    fn rejects_unknown_collector() {
540	        let text = format!("{MINIMAL_WATCH}\n[watch.baseline]\nsnapshot_collectors = [\"nope\"]\n");
541	        assert!(Config::parse(&text).is_err());
542	    }
543	}
