1	//! config.toml の読み込みと検証。
2	
3	use crate::paths::is_safe_name;
4	use crate::trigger::Expr;
5	use anyhow::{Context, Result, bail, ensure};
6	use log::LevelFilter;
7	use serde::{Deserialize, Deserializer};
8	use std::collections::HashSet;
9	use std::path::Path;
10	use std::time::Duration;
11	
12	#[derive(Debug, Deserialize)]
13	#[serde(deny_unknown_fields)]
14	pub struct Config {
15	    #[serde(default)]
16	    pub general: General,
17	    #[serde(default)]
18	    pub backends: Backends,
19	    #[serde(default, rename = "watch")]
20	    pub watches: Vec<Watch>,
21	}
22	
23	#[derive(Debug, Deserialize)]
24	#[serde(deny_unknown_fields, default)]
25	pub struct General {
26	    #[serde(deserialize_with = "log_level")]
27	    pub log_level: LevelFilter,
28	    pub log_retention_days: u32,
29	    pub incident_retention_days: u32,
30	    /// 自動で始めた調査の開始と終了をデスクトップ通知で知らせる
31	    pub notify: bool,
32	}
33	
34	impl Default for General {
35	    fn default() -> Self {
36	        Self {
37	            log_level: LevelFilter::Info,
38	            log_retention_days: 14,
39	            incident_retention_days: 30,
40	            notify: true,
41	        }
42	    }
43	}
44	
45	#[derive(Debug, Default, Deserialize)]
46	#[serde(deny_unknown_fields)]
47	pub struct Backends {
48	    pub claude_code: Option<ClaudeCodeBackend>,
49	    pub codex: Option<CodexBackend>,
50	    pub local: Option<LocalBackend>,
51	}
52	
53	#[derive(Debug, Clone, Deserialize)]
54	#[serde(deny_unknown_fields)]
55	pub struct ClaudeCodeBackend {
56	    pub command: String,
57	    #[serde(default = "default_max_turns")]
58	    pub max_turns: u32,
59	}
60	
61	#[derive(Debug, Clone, Deserialize)]
62	#[serde(deny_unknown_fields)]
63	pub struct CodexBackend {
64	    pub command: String,
65	}
66	
67	#[derive(Debug, Clone, Deserialize)]
68	#[serde(deny_unknown_fields)]
69	pub struct LocalBackend {
70	    pub endpoint: String,
71	    pub model: String,
72	    #[serde(default)]
73	    #[allow(dead_code)] // 値は読まない。analyze_only 以外の指定を拒否するために持つ
74	    pub mode: LocalMode,
75	}
76	
77	#[derive(Debug, Clone, Copy, Default, Deserialize)]
78	#[serde(rename_all = "snake_case")]
79	pub enum LocalMode {
80	    /// ツール実行なしで事件ファイルだけを分析する
81	    #[default]
82	    AnalyzeOnly,
83	}
84	
85	#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
86	#[serde(rename_all = "snake_case")]
87	pub enum BackendKind {
88	    ClaudeCode,
89	    Codex,
90	    Local,
91	}
92	
93	impl BackendKind {
94	    pub const ALL: [Self; 3] = [Self::ClaudeCode, Self::Codex, Self::Local];
95	
96	    pub fn name(self) -> &'static str {
97	        match self {
98	            Self::ClaudeCode => "claude_code",
99	            Self::Codex => "codex",
100	            Self::Local => "local",
101	        }
102	    }
103	
104	    pub fn parse(name: &str) -> Result<Self> {
105	        Self::ALL
106	            .into_iter()
107	            .find(|kind| kind.name() == name)
108	            .with_context(|| format!("unknown backend: {name}"))
109	    }
110	}
111	
112	#[derive(Debug, Deserialize)]
113	#[serde(deny_unknown_fields)]
114	pub struct Watch {
115	    pub name: String,
116	    /// 前回の probe から何秒経っていれば実行するか
117	    #[serde(default = "default_interval", deserialize_with = "duration")]
118	    pub interval: Duration,
119	    pub probe: Probe,
120	    #[serde(default)]
121	    pub baseline: Baseline,
122	    pub trigger: Option<Trigger>,
123	    pub diagnose: Option<Diagnose>,
124	}
125	
126	#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
127	#[serde(rename_all = "snake_case")]
128	pub enum ProbeKind {
129	    Tcp,
130	    Icmp,
131	    Dns,
132	    Http,
133	    Command,
134	}
135	
136	#[derive(Debug, Deserialize)]
137	#[serde(deny_unknown_fields)]
138	pub struct Probe {
139	    pub kind: ProbeKind,
140	    #[serde(default)]
141	    pub targets: Vec<String>,
142	    #[serde(default = "default_probe_timeout", deserialize_with = "duration")]
143	    pub timeout: Duration,
144	    /// kind = "dns": 問い合わせ先。省略時は OS のリゾルバを使う
145	    pub server: Option<String>,
146	    /// kind = "http": 期待するステータス。省略時は 2xx/3xx を成功とする
147	    pub expect_status: Option<u16>,
148	    /// kind = "command": 実行するコマンドと引数
149	    #[serde(default)]
150	    pub command: Vec<String>,
151	}
152	
153	#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
154	#[serde(rename_all = "snake_case")]
155	pub enum AggregateBy {
156	    WeekdayHour,
157	    Hour,
158	    None,
159	}
160	
161	#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
162	#[serde(try_from = "String")]
163	pub enum CollectorSpec {
164	    Adapters,
165	    Routes,
166	    DnsConfig,
167	    Traceroute(String),
168	}
169	
170	impl CollectorSpec {
171	    pub fn name(&self) -> String {
172	        match self {
173	            Self::Adapters => "adapters".to_string(),
174	            Self::Routes => "routes".to_string(),
175	            Self::DnsConfig => "dns_config".to_string(),
176	            Self::Traceroute(target) => format!("traceroute:{target}"),
177	        }
178	    }
179	}
180	
181	impl TryFrom<String> for CollectorSpec {
182	    type Error = String;
183	
184	    fn try_from(value: String) -> std::result::Result<Self, String> {
185	        match value.as_str() {
186	            "adapters" => Ok(Self::Adapters),
187	            "routes" => Ok(Self::Routes),
188	            "dns_config" => Ok(Self::DnsConfig),
189	            other => match other.strip_prefix("traceroute:") {
190	                Some(target) if !target.is_empty() => Ok(Self::Traceroute(target.to_string())),
191	                _ => Err(format!("unknown collector: {other}")),
192	            },
193	        }
194	    }
195	}
196	
197	#[derive(Debug, Deserialize)]
198	#[serde(deny_unknown_fields, default)]
199	pub struct Baseline {
200	    #[serde(deserialize_with = "duration")]
201	    pub metrics_retention: Duration,
202	    pub aggregate_by: AggregateBy,
203	    /// これ未満の時間帯は全体の統計で代用する
204	    pub min_samples: u64,
205	    pub snapshot_collectors: Vec<CollectorSpec>,
206	    #[serde(deserialize_with = "duration")]
207	    pub snapshot_interval: Duration,
208	    pub keep_good_snapshots: u32,
209	}
210	
211	impl Default for Baseline {
212	    fn default() -> Self {
213	        Self {
214	            metrics_retention: Duration::from_secs(7 * 86400),
215	            aggregate_by: AggregateBy::WeekdayHour,
216	            min_samples: 30,
217	            snapshot_collectors: Vec::new(),
218	            snapshot_interval: Duration::from_secs(6 * 3600),
219	            keep_good_snapshots: 5,
220	        }
221	    }
222	}
