301	/// "500ms" "3s" "5m" "6h" "7d" 形式の期間を解釈する
302	pub fn parse_duration(text: &str) -> std::result::Result<Duration, String> {
303	    let error = || format!("invalid duration: {text:?} (expected e.g. 500ms, 3s, 5m, 6h, 7d)");
304	    let split = text.find(|c: char| !c.is_ascii_digit()).ok_or_else(error)?;
305	    let (number, unit) = text.split_at(split);
306	    let number: u64 = number.parse().map_err(|_| error())?;
307	    let millis = match unit {
308	        "ms" => Some(1),
309	        "s" => Some(1000),
310	        "m" => Some(60_000),
311	        "h" => Some(3_600_000),
312	        "d" => Some(86_400_000),
313	        _ => None,
314	    };
315	    millis
316	        .and_then(|unit| number.checked_mul(unit))
317	        .map(Duration::from_millis)
318	        .ok_or_else(error)
319	}
