321	impl Config {
322	    pub fn load(path: &Path) -> Result<Self> {
323	        let text = std::fs::read_to_string(path)
324	            .with_context(|| format!("failed to read {}", path.display()))?;
325	        Self::parse(&text).with_context(|| format!("invalid config: {}", path.display()))
326	    }
327	
328	    fn parse(text: &str) -> Result<Self> {
329	        let config: Self = toml::from_str(text)?;
330	        config.validate()?;
331	        Ok(config)
332	    }
333	
334	    pub fn watch(&self, name: &str) -> Result<&Watch> {
335	        self.watches
336	            .iter()
337	            .find(|watch| watch.name == name)
338	            .with_context(|| format!("no such watch: {name}"))
339	    }
340	
341	    fn backend_defined(&self, kind: BackendKind) -> bool {
342	        match kind {
343	            BackendKind::ClaudeCode => self.backends.claude_code.is_some(),
344	            BackendKind::Codex => self.backends.codex.is_some(),
345	            BackendKind::Local => self.backends.local.is_some(),
346	        }
347	    }
348	
349	    fn validate(&self) -> Result<()> {
350	        let mut names = HashSet::new();
351	        for watch in &self.watches {
352	            // ディレクトリ名と systemd のユニット名にそのまま使うので文字種を絞る
353	            ensure!(
354	                is_safe_name(&watch.name),
355	                "watch name must be [A-Za-z0-9_-]+: {:?}",
356	                watch.name
357	            );
358	            ensure!(
359	                names.insert(&watch.name),
360	                "duplicate watch name: {}",
361	                watch.name
362	            );
363	            self.validate_watch(watch)
364	                .with_context(|| format!("watch {:?}", watch.name))?;
365	        }
366	        Ok(())
367	    }
368	
369	    fn validate_watch(&self, watch: &Watch) -> Result<()> {
370	        watch.probe.validate()?;
371	        if let Some(trigger) = &watch.trigger {
372	            ensure!(trigger.consecutive >= 1, "consecutive must be at least 1");
373	        }
374	        if let Some(diagnose) = &watch.diagnose {
375	            for kind in std::iter::once(diagnose.backend).chain(diagnose.fallback) {
376	                ensure!(
377	                    self.backend_defined(kind),
378	                    "backend {} is not configured in [backends]",
379	                    kind.name()
380	                );
381	            }
382	        }
383	        Ok(())
384	    }
385	}
