387	impl Probe {
388	    fn validate(&self) -> Result<()> {
389	        if self.kind == ProbeKind::Command {
390	            ensure!(!self.command.is_empty(), "command probe needs `command`");
391	            ensure!(self.targets.is_empty(), "command probe takes no `targets`");
392	            return Ok(());
393	        }
394	        ensure!(!self.targets.is_empty(), "probe needs `targets`");
395	        for target in &self.targets {
396	            match self.kind {
397	                ProbeKind::Tcp => {
398	                    let has_port = target
399	                        .rsplit_once(':')
400	                        .is_some_and(|(_, port)| port.parse::<u16>().is_ok());
401	                    if !has_port && target != "gateway" {
402	                        bail!("tcp target needs a port: {target}");
403	                    }
404	                }
405	                ProbeKind::Http => {
406	                    if !target.starts_with("http://") && !target.starts_with("https://") {
407	                        bail!("http target must be a URL: {target}");
408	                    }
409	                }
410	                ProbeKind::Icmp | ProbeKind::Dns | ProbeKind::Command => {}
411	            }
412	        }
413	        Ok(())
414	    }
415	}
