415	                    available.join(", ")
416	                );
417	            }
418	        }
419	        if let Some(diagnose) = &watch.diagnose {
420	            for kind in std::iter::once(diagnose.backend).chain(diagnose.fallback) {
421	                ensure!(
422	                    self.backend_defined(kind),
