326	/// "500ms" "3s" "5m" "6h" "7d" 形式の期間を解釈する
327	pub fn parse_duration(text: &str) -> std::result::Result<Duration, String> {
328	    let error = || format!("invalid duration: {text:?} (expected e.g. 500ms, 3s, 5m, 6h, 7d)");
329	    let split = text.find(|c: char| !c.is_ascii_digit()).ok_or_else(error)?;
330	    let (number, unit) = text.split_at(split);
331	    let number: u64 = number.parse().map_err(|_| error())?;
332	    let millis = match unit {
333	        "ms" => Some(1),
334	        "s" => Some(1000),
335	        "m" => Some(60_000),
336	        "h" => Some(3_600_000),
337	        "d" => Some(86_400_000),
338	        _ => None,
339	    };
340	    millis
341	        .and_then(|unit| number.checked_mul(unit))
342	        .map(Duration::from_millis)
343	        .ok_or_else(error)
344	}
