400	            );
401	        } else {
402	            ensure!(
403	                watch.baseline.learn_for.is_none(),
404	                "`learn_for` is only for kind = \"process\""
405	            );
406	        }
407	        if let Some(trigger) = &watch.trigger {
408	            ensure!(trigger.consecutive >= 1, "consecutive must be at least 1");
409	            // 式の変数は probe の種類で決まるので、パースではなくここで照合する
410	            let available = trigger::variables_for(watch.probe.kind);
411	            for name in trigger.when.variables() {
