432	impl Probe {
433	    fn validate(&self) -> Result<()> {
434	        if self.kind == ProbeKind::Process {
435	            ensure!(self.targets.is_empty(), "process probe takes no `targets`");
436	            ensure!(self.command.is_empty(), "process probe takes no `command`");
437	            return Ok(());
438	        }
439	        ensure!(
440	            self.expected.is_empty() && self.ignore.is_empty(),
441	            "`expected` and `ignore` are only for kind = \"process\""
442	        );
443	        if self.kind == ProbeKind::Command {
444	            ensure!(!self.command.is_empty(), "command probe needs `command`");
445	            ensure!(self.targets.is_empty(), "command probe takes no `targets`");
446	            return Ok(());
447	        }
448	        ensure!(!self.targets.is_empty(), "probe needs `targets`");
449	        for target in &self.targets {
450	            match self.kind {
451	                ProbeKind::Tcp => {
452	                    let has_port = target
453	                        .rsplit_once(':')
454	                        .is_some_and(|(_, port)| port.parse::<u16>().is_ok());
455	                    if !has_port && target != "gateway" {
456	                        bail!("tcp target needs a port: {target}");
457	                    }
458	                }
459	                ProbeKind::Http => {
460	                    if !target.starts_with("http://") && !target.starts_with("https://") {
461	                        bail!("http target must be a URL: {target}");
462	                    }
463	                }
464	                ProbeKind::Icmp | ProbeKind::Dns | ProbeKind::Command | ProbeKind::Process => {}
465	            }
466	        }
467	        Ok(())
468	    }
469	}
