        let c = observe(&mut store, &w, &procs, 1100, true);
        assert_eq!(metric(&c, "unknown"), 1.0);
    }

    #[test]
    fn masquerade_is_not_learned_as_normal() {
        let mut store = Store::in_memory().unwrap();
