        let procs = [
            proc(10, "notepad.exe", Some(NOTEPAD)),
            proc(11, "svchost.exe", Some(FAKE_SVCHOST)),
        ];
        let c = observe(&mut store, &w, &procs, 1000, true);
        assert_eq!(metric(&c, "masquerade"), 1.0);
        assert_eq!(metric(&c, "unknown"), 1.0);
        assert_eq!(c.learned, 1);
        assert_eq!(
