use super::Sample;
use crate::exec;
use std::time::{Duration, Instant};

/// 終了コード 0 を成功とする。標準出力の最終行が数値なら `value` 指標になる
pub fn check(argv: &[String], timeout: Duration) -> Result<Sample, String> {
    let mut command = exec::command(&argv[0]);
    command.args(&argv[1..]);
    let started = Instant::now();
    let output = exec::run(command, None, timeout).map_err(|e| format!("{e:#}"))?;
    let rtt_ms = started.elapsed().as_secs_f64() * 1000.0;

    if output.timed_out {
        return Err(format!("timed out after {timeout:?}"));
    }
    if !output.success() {
        return Err(format!(
            "exit code {:?}: {}",
            output.code,
            output.stderr.trim()
        ));
    }
    Ok(Sample {
        rtt_ms: Some(rtt_ms),
        value: parse_value(&output.stdout),
    })
}

fn parse_value(stdout: &str) -> Option<f64> {
    stdout
        .lines()
        .rev()
        .find(|line| !line.trim().is_empty())?
        .trim()
        .parse()
        .ok()
        .filter(|value: &f64| value.is_finite())
}

