/// プロセスを既知の集合と照らして分類する。
///
/// 学習してよいのは正常な回だけ。正常かどうかは条件式の成否で決まるが、その式の変数は
/// 分類の結果に依存する。そこで、まず学習する前提で分類し、式が成立したら（異常なら）
/// 何も学習しない前提でやり直す。やり直すと pending が増えるだけなので、成立したままになる
fn classify_processes(
    store: &Store,
    paths: &Paths,
    watch: &Watch,
    processes: &[ProcessInfo],
    metrics: &Variables,
    now: i64,
) -> Result<Classification> {
    let roots = Roots::from_env();
    // kuda 自身と、実行中の調査プロセス（detach されていて親子ではたどれない）
    let mut excluded: Vec<_> = known_set::own_root(processes).into_iter().collect();
    excluded.extend(investigation::running(paths, processes));
    let classify =
        |learn| known_set::classify(store, watch, processes, &excluded, &roots, now, learn);
    let classification = classify(true)?;
    if classification.learned == 0 {
        return Ok(classification);
    }
    let mut variables = metrics.clone();
    variables.extend(classification.metrics.clone());
    if trigger_matches(watch, &variables) {
        return classify(false);
    }
    Ok(classification)
}

#[allow(clippy::too_many_arguments)]
fn fire(
    store: &mut Store,
    paths: &Paths,
    watch: &Watch,
    run: &ProbeRun,
    stats: &[SeriesStats],
    since: i64,
    reason: &str,
    pending: &[String],
) -> Result<()> {
    let incident = build_incident(store, paths, watch, run, stats, since, reason)?;
    log::warn!(
        if process.pid < entry.process.pid {
            entry.process = process;
        }
        entry.masquerade |= masquerade;
    }

    let started = store.learning_started(&watch.name)?.unwrap_or(now);
    let learning = watch
        .baseline
        .learn_for
        .is_some_and(|d| now < started.saturating_add(d.as_secs() as i64));
    let statuses = store.identity_statuses(&watch.name)?;

    let mut seen = Vec::new();
    let mut pending = Vec::new();
    let mut learned = 0;
    for (key, o) in &observed {
        let status = match statuses.get(key) {
            Some(status) => *status,
            // 偽装は、学習期間中でも正常として覚えない
            None if learn && learning && !o.masquerade => {
                learned += 1;
                IdentityStatus::Known
            }
            None => IdentityStatus::Pending,
        };
        seen.push((key.clone(), status));
        if status == IdentityStatus::Pending {
            pending.push(PendingProcess {
                identity: o.identity.clone(),
                process: o.process.clone(),
                user_writable: o.user_writable,
                masquerade: o.masquerade,
            });
        }
    }

    let count = |f: fn(&PendingProcess) -> bool| pending.iter().filter(|p| f(p)).count() as f64;
    let missing = probe
        .expected
        .iter()
        .filter(|g| !observed.keys().any(|key| glob_match(g, key)))
        .count();
    let mut metrics = Variables::new();
    metrics.insert("unknown".to_string(), pending.len() as f64);
    metrics.insert(
        "unknown_user_writable".to_string(),
        count(|p| p.user_writable),
    );
    metrics.insert("masquerade".to_string(), count(|p| p.masquerade));
    metrics.insert("missing".to_string(), missing as f64);
    metrics.insert("process_count".to_string(), observed.len() as f64);
    Ok(Classification {
        metrics,
        pending,
        learned,
        );
    }
}

fn build_incident(
    store: &Store,
    paths: &Paths,
    watch: &Watch,
    run: &ProbeRun,
    stats: &[SeriesStats],
