    reason: &str,
) -> Result<Incident> {
    let created = now();
    let current = collector::take_snapshot(&watch.baseline.snapshot_collectors, created);
    let collectors: Vec<String> = watch
        .baseline
        .snapshot_collectors
        .iter()
        .map(|spec| spec.name())
        .collect();

