                for target in &targets {
                    let has_port = target
                        .rsplit_once(':')
                        .is_some_and(|(_, port)| port.parse::<u16>().is_ok());
                    if !has_port && target != "gateway" {
                        bail!("tcp target needs a port: {target}");
                    }
                }
                Ok(ProbeSpec::Tcp { targets, timeout })
            }
