                need_targets()?;
                for target in &targets {
                    if !target.starts_with("http://") && !target.starts_with("https://") {
                        bail!("http target must be a URL: {target}");
                    }
                }
                Ok(ProbeSpec::Http {
                    targets,
                    expect_status,
                    timeout,
                })
            }
            ProbeKind::Icmp => {
                need_targets()?;
                Ok(ProbeSpec::Icmp { targets, timeout })
            }
            ProbeKind::Dns => {
                need_targets()?;
                Ok(ProbeSpec::Dns {
                    targets,
                    server,
                    timeout,
                })
            }
        }
    }
}

